using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Xml;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class AngleSegments {
 internal static List<SteelCutDemand> Expand(SteelCutDemand source,double spliceExtra){SteelWeight.Positive(source.Length,source.KgM);SteelWeight.Count(source.Quantity);if(double.IsNaN(spliceExtra)||double.IsInfinity(spliceExtra)||spliceExtra<0||spliceExtra>=6)throw new Exception("Angle splice extra length per joint must be nonnegative and less than 6 m.");source.Joints=0;source.SpliceExtra=0;if(source.Length<=6+1e-9)return new List<SteelCutDemand>{source};double count=Math.Ceiling((source.Length-6-1e-9)/(6-spliceExtra))+1;if(count*source.Quantity>100000)throw new Exception("Angle cutting plan supports up to 100000 cut pieces.");var result=new List<SteelCutDemand>();double remaining=source.Length;int segment=1;while(remaining>6+1e-9){result.Add(new SteelCutDemand{Member=source.Member+" / segment "+segment++,Specification=source.Specification,Length=6,KgM=source.KgM,Quantity=source.Quantity,Source=source});remaining-=6-spliceExtra;}result.Add(new SteelCutDemand{Member=source.Member+" / segment "+segment,Specification=source.Specification,Length=remaining,KgM=source.KgM,Quantity=source.Quantity,Source=source});source.Joints=result.Count-1;source.SpliceExtra=spliceExtra;return result;}
}
partial class ProgramOfWorksForm {
 TextBox angleSpliceExtra;
 void ConfigureAngleSegments(){angleSpliceExtra=new TextBox{Width=110,AccessibleName="Angle splice extra length metres per joint"};var page=(TabPage)steelAngles.Parent;var tools=page.Controls.OfType<FlowLayoutPanel>().First();tools.Controls.Add(new Label{Text="Splice extra length m / joint",AutoSize=true,Padding=new Padding(0,8,0,0)});tools.Controls.Add(angleSpliceExtra);tools.Controls.Add(new Label{Text="Optional approved allowance; blank adds no extra length.",AutoSize=true,Padding=new Padding(8,8,0,0)});tools.Visible=true;angleSpliceExtra.TextChanged+=(s,e)=>{if(!filling&&!initializingWorks)Recalculate();};}
 double AngleSpliceExtra(){if(angleSpliceExtra==null||string.IsNullOrWhiteSpace(angleSpliceExtra.Text))return 0;double value;if(!double.TryParse(angleSpliceExtra.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value)||value<0||value>=6)throw new Exception("Enter an angle splice extra length from 0 up to, but less than, 6 m per joint.");return value;}
}
}
